SELECT t.*

AND t.PARENT_ID = 0 AND b.TYPE IN ('NORMAL', 'CATEGORY')
AND b.PROJECT_ID = #{req.projectId}
AND b.LAYER_ID = #{req.layerId}
AND b.NAME LIKE CONCAT(CONCAT('%', #{req.name}), '%')
AND b.TYPE = #{req.type}
ORDER BY t.ID DESC

SELECT t.*

AND t.PARENT_ID = 0 AND t.MODEL_ID = #{modelId}
ORDER BY t.ID DESC

SELECT t.*

AND t.PARENT_ID = 0 AND t.INSTANCE_ID = #{instanceId}
ORDER BY t.ID DESC

SELECT t.*

AND t.PARENT_ID = b.ID AND t.MODEL_ID = #{submodelId} AND t.INSTANCE_ID = #{instanceId}
ORDER BY t.ID DESC
